academicYears.message:
Invalid `prisma.class.findUnique()` invocation:

{
  where: {
+   id: Int
  },
  include: {
    classTeacher: true,
    academicYear: true,
    subjects: {
      include: {
        subject: true,
        teacher: {
          select: {
            id: true,
            fullName: true
          }
        }
      }
    },
    enrollments: {
      where: {
        isActive: true
      },
      include: {
        student: {
          select: {
            id: true,
            fullName: true,
            studentId: true,
            gender: true,
            photoUrl: true
          }
        }
      },
      orderBy: {
        rollNo: "asc"
      }
    }
  }
}

Argument `id` is missing.
